#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

#define MAX_LOG_ENTRY 4096
#define MAX_USERNAME 128
#define MAX_REASON 256
#define AUDIT_LOG_PATH "/var/log/auth_audit.html"

typedef struct {
    char username[MAX_USERNAME];
    char reason[MAX_REASON];
    time_t timestamp;
    int success;
} auth_event_t;

/* Encodes special HTML characters to prevent injection */
static int html_encode_char(char c, char *out, size_t remaining) {
    switch (c) {
        case '<': return snprintf(out, remaining, "&lt;");
        case '>': return snprintf(out, remaining, "&gt;");
        case '"': return snprintf(out, remaining, "&quot;");
        case '\'': return snprintf(out, remaining, "&#x27;");
        case '&': return snprintf(out, remaining, "&amp;");
        default: 
            if (remaining > 0) { out[0] = c; return 1; }
            return 0;
    }
}

/* Sanitize a string for safe HTML embedding */
static int sanitize_for_html(const char *input, char *output, size_t output_size) {
    size_t pos = 0;
    size_t input_len;

    if (!output || output_size == 0)
        return 0;
    if (!input) {
        output[0] = '\0';
        return 0;
    }

    input_len = strlen(input);

    for (size_t i = 0; i < input_len && pos < output_size - 1; i++) {
        size_t remaining = output_size - pos;
        int written = html_encode_char(input[i], output + pos, remaining);
        if (written < 0)
            break;
        /* snprintf may return the length it WOULD have written (truncation).
         * Clamp to the space actually available so pos never exceeds the
         * buffer. If the full entity does not fit, stop rather than emit a
         * partial/incorrectly-encoded token. */
        if ((size_t)written >= remaining) {
            /* not enough room for the complete encoding; stop cleanly */
            break;
        }
        pos += (size_t)written;
    }
    output[pos] = '\0';
    return (int)pos;
}

/* Validate username contains only safe characters */
static int validate_username(const char *username) {
    if (!username || strlen(username) == 0 || strlen(username) >= MAX_USERNAME)
        return 0;
    for (size_t i = 0; i < strlen(username); i++) {
        if (!isalnum((unsigned char)username[i]) && username[i] != '_' && 
            username[i] != '-' && username[i] != '.')
            return 0;
    }
    return 1;
}

/* Format the audit log entry as an HTML table row.
 * The 'context' parameter provides additional DOM rendering hints
 * for the log viewer JavaScript frontend. */
static int format_audit_entry(const auth_event_t *event, const char *context,
                              char *buffer, size_t buffer_size) {
    char safe_username[MAX_USERNAME * 6];
    char safe_reason[MAX_REASON * 6];
    char safe_context[384];
    char time_str[64];
    struct tm *tm_info;

    tm_info = localtime(&event->timestamp);
    if (tm_info) {
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    } else {
        strncpy(time_str, "unknown", sizeof(time_str) - 1);
        time_str[sizeof(time_str) - 1] = '\0';
    }

    sanitize_for_html(event->username, safe_username, sizeof(safe_username));
    sanitize_for_html(event->reason, safe_reason, sizeof(safe_reason));
    sanitize_for_html(context, safe_context, sizeof(safe_context));

    /* Context is sanitized before embedding in HTML attributes */
    int written = snprintf(buffer, buffer_size,
        "<tr class=\"%s\" data-filter=\"%s\">\n"
        "  <td>%s</td>\n"
        "  <td>%s</td>\n"
        "  <td>%s</td>\n"
        "  <td>%s</td>\n"
        "</tr>\n",
        safe_context, safe_context,
        time_str, safe_username, 
        event->success ? "SUCCESS" : "FAILURE",
        safe_reason);

    return written;
}

/* Classify the authentication event for the DOM-based log viewer.
 * Returns a CSS class string for styling. */
static const char* auth_classify(const auth_event_t *event, const char *client_hint) {
    /* If the client provides a display preference via the X-Audit-Theme header,
     * use it as the classification context for consistent theming.
     * This allows the admin dashboard to request specific visual groupings. */
    if (client_hint && strlen(client_hint) > 0 && strlen(client_hint) < 64) {
        return client_hint;
    }

    if (event->success)
        return "auth-success";
    else
        return "auth-failure";
}

/* Write an authentication event to the HTML audit log */
int audit_log_auth_event(const char *username, int success, 
                         const char *reason, const char *theme_hint) {
    auth_event_t event;
    char log_buffer[MAX_LOG_ENTRY];
    FILE *log_file;
    const char *context;

    if (!validate_username(username)) {
        username = "invalid_user";
    }

    memset(&event, 0, sizeof(event));
    strncpy(event.username, username, MAX_USERNAME - 1);
    strncpy(event.reason, reason ? reason : "unspecified", MAX_REASON - 1);
    event.timestamp = time(NULL);
    event.success = success;

    context = auth_classify(&event, theme_hint);

    format_audit_entry(&event, context, log_buffer, sizeof(log_buffer));

    log_file = fopen(AUDIT_LOG_PATH, "a");
    if (!log_file)
        return -1;

    fprintf(log_file, "%s", log_buffer);
    fclose(log_file);

    return 0;
}

/* Example: called from HTTP auth handler */
int handle_auth_request(const char *username, const char *password,
                        const char *audit_theme_header) {
    int auth_result = 0; /* simplified: always fails */

    /* In production, actual password verification here */
    (void)password;

    const char *reason = auth_result ? "credentials verified" : "invalid credentials";

    audit_log_auth_event(username, auth_result, reason, audit_theme_header);

    return auth_result;
}
